{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can independently solve and explain one changed simple series circuit using Ohm's law, without help."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "Explain and use Ohm's law for one simple series circuit. Stop once I can solve and explain one changed circuit independently.",
