  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
          "explanation": "The learner reports a specific conceptual confusion between current and potential difference and cannot explain why circuit rules hold. With no deadline and no prior completed work, the smallest useful strategy is one integrated conceptual activity that directly contrasts current and potential difference, builds the conservation reasoning behind circuit rules, and applies both to a changed circuit problem. This addresses all three scope nodes in a single coherent task rather than separate relearning, practice, and check stages, because the confusion is conceptual and an integrated explanation plus supported application plus an independent changed example can meet the goal cleanly. No separate remediation is committed unless the integrated task reveals a concrete failure.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "concept_integration",
              "title": "Concept integration and application",
              "outcome": "Distinguish current from potential difference, explain why circuit rules hold, and solve a changed circuit problem independently.",
              "effort": {
                "lowMinutes": 60,
                "likelyMinutes": 90,
                "highMinutes": 120
              },
              "readinessCriterion": "Correctly distinguishes current from potential difference, gives a valid conservation-based explanation of circuit rules, and solves a changed circuit problem without confusing the two concepts."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Directly contrast current (rate of charge flow) with potential difference (energy per unit charge) using a concrete circuit example, so the learner can state what each quantity measures and why they are not interchangeable."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Use conservation of charge at a junction and conservation of energy around a loop to explain why Kirchhoff's rules hold, linking the rules to the underlying physical principles rather than memorized formulas."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Apply the corrected concepts and conservation reasoning to a changed circuit problem, requiring correct method choice and a correct solution without assistance."
          }
        ],
        "activities": [
          {
            "localId": "concept_application",
            "outcomeRefs": [
              "concept_integration"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Contrast current and potential difference, explain circuit rules, and solve a changed circuit problem",
            "activityType": "Integrated conceptual explanation and problem solving",
            "purpose": "Resolve the current-versus-potential-difference confusion, build a conservation-based explanation of circuit rules, and verify independent problem solving on a changed circuit.",
            "instructions": "Work through this in one sitting, using only methods you have actually been taught. 1) Write a clear contrast between current and potential difference: define each, state its unit, and give one concrete circuit example where changing one does not change the other. 2) Explain why circuit rules hold: use conservation of charge at a junction and conservation of energy around a loop to justify the junction and loop rules. 3) Solve the following changed circuit problem without assistance. A circuit has a 12 V battery connected to two resistors in series, R1 = 4 ohm and R2 = 2 ohm. (a) State which quantity is the same through both resistors and which quantity differs, and explain why in terms of your contrast from step 1. (b) Use the loop rule to find the current. (c) Find the potential difference across each resistor. (d) Check that the sum of the potential differences equals the battery voltage. 4) If you find yourself confusing current and potential difference at any point, stop and re-read your step 1 contrast before continuing. Do not use advanced methods beyond what you have been taught; if you attempt an unfamiliar method, treat it as optional exploration, not a required part of this task.",
            "completionCriterion": "You produce a correct written contrast between current and potential difference, a valid conservation-based explanation of why circuit rules hold, and a correct solution to the changed circuit problem (current = 2 A, potential differences = 8 V and 4 V, sum = 12 V) with no confusion between the two concepts.",
            "effort": {
              "lowMinutes": 60,
              "likelyMinutes": 90,
              "highMinutes": 120
            },
            "timeboxMinutes": 120,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 60,
                "completionCriterion": "Completed the written contrast between current and potential difference and the conservation-based explanation of circuit rules."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "Only one integrated activity is committed; separate drill sets, multiple practice rounds, and a second check are omitted because the integrated task can meet the goal cleanly and no concrete failure has been observed."
          ],
          "unresolvedUncertainty": [
            "The learner's exact taught repertoire of circuit methods is not specified, so the task restricts itself to series circuits and basic conservation rules and treats advanced methods as optional."
          ],
          "stoppingConditions": [
            "Stop after the integrated activity if the completion criterion is met; do not add further practice or checks unless the activity reveals a concrete failure."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan commits one integrated 120-minute activity that contrasts current with potential difference, explains circuit rules via conservation, and solves a changed series circuit. This addresses all three scope nodes without separate relearning, practice, and check stages, because the reported weakness is conceptual and an integrated explanation plus application can resolve it. Separate drills and a second check are left out; they would only be added if the integrated task reveals a concrete failure. No deadline exists, so the learner can finish early if the criterion is met."
}

