{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You finish one integrated method-selection session on unfamiliar circuits: you name the applicable law, justify why its assumptions hold, solve the circuit correctly, and self-check the result."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I can explain voltage and current but choose the wrong law on unfamiliar circuits. Focus on selecting and applying the method.",
          "explanation": "Your conceptual understanding of voltage and current is reported as secure; the weakness is method selection on unfamiliar circuits. That does not warrant relearning basic concepts, multiple practice sets, or a separate check. One integrated session that forces you to choose, justify, and apply the method on changed circuits directly targets the weakness and gives clean evidence of selection capability. Further remediation is left contingent on an observed selection failure in that session, not booked in advance.",
          "recommendedEffort": {
            "lowMinutes": 25,
            "likelyMinutes": 40,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "method_selection",
              "title": "Method selection on unfamiliar circuits",
              "outcome": "Choose the applicable circuit law on changed circuits, justify the choice from its assumptions, and solve correctly.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 40,
                "highMinutes": 60
              },
              "readinessCriterion": "Correct method choice, valid selection reason, and correct solution on at least two unfamiliar circuits without assistance, using only methods already taught."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Addressed by the integrated method-selection activity: choosing and applying the correct circuit law on unfamiliar circuits."
          }
        ],
        "activities": [
          {
            "localId": "method_selection_session",
            "outcomeRefs": [
              "method_selection"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Choose and justify the circuit method on unfamiliar circuits",
            "activityType": "Integrated method-selection practice",
            "purpose": "Turn secure voltage/current understanding into reliable selection and application of the correct circuit law on changed circuits.",
            "instructions": "Using only circuit-analysis methods you have already been taught (for example, Ohm's law, series/parallel equivalent resistance, voltage divider, current divider, and Kirchhoff's laws as covered in your course), work through three unfamiliar circuits of increasing unfamiliarity. For each circuit: (1) list which method(s) could apply; (2) choose one method and state the specific assumptions or topology that make it valid here; (3) solve for the requested quantity showing the key steps; (4) check the result by an independent route (for example, power balance, a known limiting case, or a second valid method) and state whether the check agrees. If a chosen method fails because its assumptions do not hold, explain why and choose the correct one. Do not use methods beyond your taught repertoire; if you meet a circuit that seems to require an unfamiliar advanced method, note it and skip it rather than guessing. Finish when you have at least two fully solved unfamiliar circuits with correct method choice, valid justification, correct answers, and a completed check.",
            "completionCriterion": "At least two unfamiliar circuits are solved with the correct method, a valid assumption-based justification, correct numerical results, and an independent check that agrees; any failed method choice is explained and corrected.",
            "effort": {
              "lowMinutes": 25,
              "likelyMinutes": 40,
              "highMinutes": 60
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "method_selection_remediation",
            "outcomeRefs": [
              "method_selection"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted remediation for a failed method choice",
            "activityType": "Failure-triggered method-selection repair",
            "purpose": "Repair a specific observed method-selection failure with a short explanation and one corrected circuit, without repeating already verified work.",
            "instructions": "If, during the integrated session, a method choice was wrong on a circuit because its assumptions or topology did not apply, revisit that circuit only: state in your own words why the chosen method failed, identify the correct method and the assumption/topology that makes it valid, and re-solve that circuit correctly with a check. Do not redo circuits already solved correctly.",
            "completionCriterion": "The specific failed circuit is explained, re-solved with the correct method, and checked successfully.",
            "effort": {
              "lowMinutes": 10,
              "likelyMinutes": 15,
              "highMinutes": 25
            },
            "timeboxMinutes": 25,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "method_selection_session",
                "condition": "A method choice on an unfamiliar circuit is wrong because its assumptions or topology do not apply."
              }
            },
            "hardDependencies": [
              "method_selection_session"
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "No separate conceptual relearning of voltage and current is booked, because that understanding is reported secure; the session spends its time on selection instead.",
            "No second full check is booked; the independent check inside each solved circuit provides the evidence, and extra remediation is contingent on an actual selection failure."
          ],
          "unresolvedUncertainty": [
            "The exact taught method repertoire is not enumerated, so the session is restricted to methods the learner confirms as already taught."
          ],
          "stoppingConditions": [
            "Stop after two unfamiliar circuits are solved, justified, and checked, or when the timebox ends, whichever comes first.",
            "Additional remediation runs only if the contingent trigger fires."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan trades breadth of practice for one focused integrated session, because your reported weakness is method selection rather than concept gaps. Relearning voltage and current and a second full check are deliberately not booked; they would add time without new evidence. Remediation is kept contingent on an actual failed method choice, so a clean session ends at the checkpoint without extra work."
}

