{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "A working Python script that reads a small expenses CSV with csv.reader, prints the header and each parsed row, and cleanly reports (rather than crashes on) a row with a wrong number of fields."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a small CSV expenses report in Python that groups by category, reports totals, and checks malformed rows, starting from no prior experience reading a CSV in Python.",
          "explanation": "The learner has never read a CSV in Python, so the useful next checkpoint is a first working prerequisite: opening a small expenses CSV with the standard csv module, seeing the parsed rows, and detecting a malformed row instead of crashing. Grouping totals and the finished report remain strategic and unbooked until this checkpoint is independently demonstrated. A single integrated 40-minute activity is enough for this checkpoint; more capacity does not justify more work.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 40,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "phase_read",
              "title": "Read and check CSV rows",
              "outcome": "A script that reads the expenses CSV, prints parsed rows, and reports malformed rows without crashing.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 40,
                "highMinutes": 60
              },
              "readinessCriterion": "The learner runs the script on a small CSV and correctly explains how it detected and reported a row with the wrong number of fields."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The next checkpoint: open a CSV with csv.reader and inspect parsed rows."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Strategic later step: group rows by category and sum totals."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Begins at the checkpoint by reporting rows whose field count is wrong; fuller validation remains strategic."
          },
          {
            "scopeRef": "scope_4",
            "disposition": "INCLUDED",
            "contribution": "The eventual small report that combines reading, grouping and malformed-row handling."
          }
        ],
        "activities": [
          {
            "localId": "read_csv",
            "outcomeRefs": [
              "phase_read"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_3"
            ],
            "title": "Read an expenses CSV and report malformed rows",
            "activityType": "Guided coding practice",
            "purpose": "Establish the prerequisite of reading CSV rows in Python and detecting a malformed row before moving to grouping and the full report.",
            "instructions": "Create a small file expenses.csv with a header row category,amount and at least four data rows, including one row that has a missing or extra field (for example a row with three values). Write a Python script that uses the standard csv module and csv.reader to open the file and print the header and each parsed row. Then add a check: for each data row, compare its number of fields to the header's number of fields, and print a clear message such as 'malformed row 3' for any row that does not match. Run the script and confirm it prints all rows and reports the malformed row without raising an uncaught error. Use only the Python constructs you have already learned; if you have not yet seen a construct (for example try/except), ask before using it rather than assuming it.",
            "completionCriterion": "The script runs on your expenses.csv, prints the header and each parsed row, and prints a clear malformed-row message for the row with the wrong number of fields, without crashing.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 40,
              "highMinutes": 60
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "stage": "First CSV reading and field-count check",
            "cognitiveDemand": "MODERATE",
            "stoppingCondition": "Stop once the script reads the CSV, prints parsed rows, and reports the malformed row; do not start grouping totals yet."
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "Grouping totals and the finished expenses report are deliberately left unbooked until the CSV-reading checkpoint is demonstrated, so the first work is a genuine prerequisite rather than a compressed version of the whole project."
          ],
          "unresolvedUncertainty": [
            "The learner's exact prior Python knowledge beyond 'never read a CSV in Python' is unknown, so the activity is written to use only already-learned constructs and to ask before using unfamiliar ones."
          ],
          "stoppingConditions": [
            "Stop after the script reads the CSV and reports a malformed row; later grouping and full-report work requires fresh evidence and an explicit request."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "This plan books only the first useful prerequisite: reading a small expenses CSV and reporting a malformed row. Grouping totals and the finished report stay strategic and unbooked because they are not needed to demonstrate the checkpoint and the learner has no prior CSV-reading experience. The single 40-minute activity fits comfortably within the 60-minute daily ceiling and finishes early rather than filling the 14-day horizon."
}

