{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Plan 1: a short CSV file is read, per-category totals are computed with a loop and dictionary, and the printed totals match a hand-check. Plan 2: the same totals dictionary is written to a JSON file with json.dump and re-read to confirm the values. This demonstrates the shared loops/dictionaries prerequisite and one working report for each target."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare a CSV totals report from a small CSV file using loops and dictionaries, with the shared loops/dictionary prerequisite owned here.",
          "explanation": "You are new to Python loops and dictionaries, so the first useful checkpoint is a small, complete CSV totals report rather than the whole eventual project. One integrated activity teaches the loop and dictionary pattern while producing a real report, and a short independent change confirms you can reuse the pattern without help. The JSON target is handled once by Plan 2, which depends on this activity; it does not re-teach the prerequisite. Later CSV features, larger files and tooling remain strategic and are not booked now.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 70,
            "highMinutes": 100
          },
          "phases": [
            {
              "localId": "p1_first_report",
              "title": "First working CSV totals report",
              "outcome": "A small CSV file is read with csv.DictReader, per-category totals are accumulated in a dictionary with a loop, and the printed totals match a hand-check.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 65
              },
              "readinessCriterion": "Your program prints per-category totals that match a manual check of the same small file."
            },
            {
              "localId": "p1_reuse_check",
              "title": "Independent reuse of the loop/dictionary pattern",
              "outcome": "The same totals pattern is applied to a second small CSV file with a different category set, without step-by-step help.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 25,
                "highMinutes": 35
              },
              "readinessCriterion": "Your program prints correct totals for the second file and you can explain in one or two sentences how the dictionary accumulates each category."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Owns the shared loops/dictionaries prerequisite: reading rows, using a loop to accumulate per-category totals in a dictionary, and reusing that pattern on a changed file."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The CSV totals report is the concrete checkpoint that applies the shared loop/dictionary pattern to real data and produces printed totals."
          }
        ],
        "activities": [
          {
            "localId": "p1_csv_totals",
            "outcomeRefs": [
              "p1_first_report"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Build a small CSV totals report with a loop and a dictionary",
            "activityType": "Guided build and independent reuse",
            "purpose": "Teaches the shared loops/dictionaries prerequisite while producing the first working CSV totals report, and confirms reuse on a different file without step-by-step help.",
            "instructions": "Use only the Python you have been taught: csv.DictReader, for loops, dictionaries, and print. Do not use pandas or other advanced libraries. Create a small CSV file such as expenses.csv with columns category,amount and at least three rows across two or three categories. In a Python file, open the CSV with csv.DictReader and use a for loop over the rows. For each row, convert the amount to a number and add it to a dictionary that maps each category to its running total; create the entry when the category is new. After the loop, print each category and its total. Hand-check the totals by adding the amounts yourself and confirm they match the printed output. Then make a second small CSV file with a different set of categories and reuse the same loop/dictionary pattern to print its totals without copying the exact first file's categories. If something fails, note the actual error and the line it points to, fix it, and re-run until the printed totals match your hand-check for both files. When finished, write one or two sentences explaining how the dictionary accumulates each category.",
            "completionCriterion": "Both small CSV files produce printed per-category totals that match your hand-check, and you can explain in one or two sentences how the dictionary accumulates each category.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 70,
              "highMinutes": 100
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 30,
                "completionCriterion": "The first CSV file is read with csv.DictReader and the loop/dictionary code prints per-category totals that match your hand-check."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "The first checkpoint covers only a small CSV totals report; larger files, extra report columns and tooling are left as later strategic work."
          ],
          "unresolvedUncertainty": [
            "How quickly you become comfortable writing a loop and dictionary from scratch is unknown until you attempt this activity."
          ],
          "stoppingConditions": [
            "Stop once both small CSV files produce totals that match your hand-check and you can explain the dictionary accumulation in one or two sentences; further practice is a later decision."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report that reuses the loops/dictionary totals from the shared prerequisite and writes and verifies the JSON output.",
          "explanation": "The loops/dictionary prerequisite is owned by Plan 1 and is not repeated here. Once the CSV totals activity is complete, the next useful checkpoint is a small JSON report that writes those totals with json.dump and re-reads the file to confirm the values. This uses the same totals dictionary rather than re-teaching it. Richer JSON structure, error handling and tooling remain strategic and are not booked now.",
          "recommendedEffort": {
            "lowMinutes": 20,
            "likelyMinutes": 35,
            "highMinutes": 50
          },
          "phases": [
            {
              "localId": "p2_json_report",
              "title": "Working JSON expenses report",
              "outcome": "The totals dictionary from the CSV work is written to a JSON file with json.dump and re-read with json.load, and the re-read values match the printed totals.",
              "effort": {
                "lowMinutes": 20,
                "likelyMinutes": 35,
                "highMinutes": 50
              },
              "readinessCriterion": "A JSON file exists with the per-category totals, and re-reading it reproduces those totals."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Reuses the shared loops/dictionaries prerequisite owned by Plan 1; no duplicate teaching or duplicate activity is created here."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report is the concrete checkpoint that serializes the shared totals dictionary and verifies the written file."
          }
        ],
        "activities": [
          {
            "localId": "p2_json_report",
            "outcomeRefs": [
              "p2_json_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "Write and verify a small JSON expenses report from the shared totals",
            "activityType": "Applied build",
            "purpose": "Turns the shared loops/dictionary totals into a working JSON report and confirms the written file by re-reading it.",
            "instructions": "Use the totals dictionary you produced in the Plan 1 CSV activity. Use only the Python you have been taught: json.dump, json.load, and the same loops/dictionary pattern. Do not use pandas or other advanced libraries. If the Plan 1 activity is not finished, wait until it is. In a Python file, import json. Build the totals dictionary for your small CSV file using the same loop pattern as before, then open a file named expenses.json in write mode and use json.dump to write the dictionary. Close the file, reopen it in read mode, and use json.load to read it back. Print the re-read totals and confirm they match the totals printed in the CSV activity. If something fails, note the actual error and the line it points to, fix it, and re-run until the re-read values match. Do not add extra features such as error handling or nested structures unless you have been taught them.",
            "completionCriterion": "expenses.json contains the per-category totals, and re-reading it with json.load reproduces the same totals that were printed in the CSV activity.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 35,
              "highMinutes": 50
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              {
                "planRef": "plan_1",
                "activityId": "p1_csv_totals"
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "The JSON checkpoint is deliberately small and uses the same totals dictionary; richer JSON structure and error handling are left as later strategic work."
          ],
          "unresolvedUncertainty": [
            "How much support you need for json.dump and json.load is unknown until you attempt this activity."
          ],
          "stoppingConditions": [
            "Stop once expenses.json is written and re-read totals match the CSV activity; further JSON features are a later decision."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "p1_csv_totals"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "p2_json_report"
      },
      "strength": "HARD",
      "reason": "The JSON report reuses the totals dictionary produced by the Plan 1 CSV activity, so the shared loops/dictionary prerequisite must be completed first."
    }
  ],
  "tradeOffExplanation": "The shared loops/dictionaries prerequisite is owned once by Plan 1's CSV totals activity, and Plan 2 depends on it instead of duplicating teaching or a second totals activity. The first checkpoint is deliberately small: one integrated CSV totals report plus a short reuse check, then a small JSON report. Larger CSV/JSON features, error handling and tooling remain strategic and unbooked until you demonstrate the checkpoint and ask for the next step."
}

